import express from "express";
import path from "path";
import { createServer as createViteServer } from "vite";

interface LeaderboardRecord {
  id: string;
  playerName: string;
  score: number;
  mode: 'arcade' | 'shootout' | 'time_attack';
  streak: number;
  avatar: string;
  country: string;
  timestamp: number;
  ballSkinId?: string;
}

// Initial mock global leaderboard with realistic competitive entries
let leaderboardData: LeaderboardRecord[] = [
  { id: '1', playerName: 'VnHoopKing 🔥', score: 142, mode: 'arcade', streak: 12, avatar: '👑', country: 'VN', timestamp: Date.now() - 3600000, ballSkinId: 'fireball' },
  { id: '2', playerName: 'DunkGod_26', score: 118, mode: 'arcade', streak: 9, avatar: '⚡', country: 'VN', timestamp: Date.now() - 7200000, ballSkinId: 'lava' },
  { id: '3', playerName: 'SlamMaster_Pro', score: 95, mode: 'arcade', streak: 7, avatar: '🏀', country: 'US', timestamp: Date.now() - 14400000, ballSkinId: 'neon' },
  { id: '4', playerName: 'HoopSniper_VN', score: 88, mode: 'arcade', streak: 6, avatar: '🎯', country: 'VN', timestamp: Date.now() - 28800000, ballSkinId: 'golden' },
  { id: '5', playerName: 'FlameShooter', score: 76, mode: 'arcade', streak: 5, avatar: '🔥', country: 'KR', timestamp: Date.now() - 86400000, ballSkinId: 'galaxy' },
  { id: '6', playerName: 'Basketballer_99', score: 64, mode: 'arcade', streak: 4, avatar: '🐯', country: 'VN', timestamp: Date.now() - 120000000, ballSkinId: 'standard' },
  
  // Shootout entries
  { id: '7', playerName: 'SniperAim_VN', score: 32, mode: 'shootout', streak: 8, avatar: '🎯', country: 'VN', timestamp: Date.now() - 5000000, ballSkinId: 'anime' },
  { id: '8', playerName: 'ArcMaster', score: 28, mode: 'shootout', streak: 6, avatar: '💫', country: 'JP', timestamp: Date.now() - 10000000, ballSkinId: 'golden' },
  { id: '9', playerName: 'SwishKing', score: 24, mode: 'shootout', streak: 5, avatar: '👑', country: 'VN', timestamp: Date.now() - 15000000, ballSkinId: 'fireball' },

  // Time Attack entries
  { id: '10', playerName: 'SpeedDemon_3P', score: 58, mode: 'time_attack', streak: 11, avatar: '⚡', country: 'VN', timestamp: Date.now() - 4000000, ballSkinId: 'fireball' },
  { id: '11', playerName: 'RapidFire_VN', score: 49, mode: 'time_attack', streak: 8, avatar: '🔥', country: 'VN', timestamp: Date.now() - 8000000, ballSkinId: 'neon' },
  { id: '12', playerName: 'Clutch3Pointer', score: 42, mode: 'time_attack', streak: 7, avatar: '🏆', country: 'SG', timestamp: Date.now() - 18000000, ballSkinId: 'standard' }
];

async function startServer() {
  const app = express();
  const PORT = 3000;

  app.use(express.json());

  // API Routes
  app.get("/api/health", (req, res) => {
    res.json({ status: "ok", appName: "Dunk Hit - Bóng Rổ Rực Lửa" });
  });

  // Get Leaderboard
  app.get("/api/leaderboard", (req, res) => {
    const mode = (req.query.mode as string) || 'arcade';
    const limit = parseInt((req.query.limit as string) || '20', 10);

    const filtered = leaderboardData
      .filter((item) => item.mode === mode)
      .sort((a, b) => b.score - a.score)
      .slice(0, limit);

    res.json({
      success: true,
      mode,
      leaderboard: filtered,
      totalEntries: leaderboardData.filter((item) => item.mode === mode).length
    });
  });

  // Submit Score
  app.post("/api/leaderboard", (req, res) => {
    const { playerName, score, mode, streak, avatar, country, ballSkinId } = req.body;

    if (!playerName || typeof score !== 'number' || !mode) {
      return res.status(400).json({ success: false, message: 'Invalid score submission data' });
    }

    const cleanName = String(playerName).trim().substring(0, 18) || 'Cầu thủ Vô Danh';
    const cleanMode = (['arcade', 'shootout', 'time_attack'].includes(mode) ? mode : 'arcade') as 'arcade' | 'shootout' | 'time_attack';

    // Check if player already exists in this mode
    const existingIndex = leaderboardData.findIndex(
      (item) => item.playerName.toLowerCase() === cleanName.toLowerCase() && item.mode === cleanMode
    );

    let isNewRecord = false;
    let entry: LeaderboardRecord;

    if (existingIndex !== -1) {
      if (score > leaderboardData[existingIndex].score) {
        leaderboardData[existingIndex].score = score;
        leaderboardData[existingIndex].streak = Math.max(leaderboardData[existingIndex].streak, streak || 0);
        leaderboardData[existingIndex].timestamp = Date.now();
        if (avatar) leaderboardData[existingIndex].avatar = avatar;
        if (ballSkinId) leaderboardData[existingIndex].ballSkinId = ballSkinId;
        isNewRecord = true;
      }
      entry = leaderboardData[existingIndex];
    } else {
      entry = {
        id: 'lb_' + Date.now() + '_' + Math.random().toString(36).substr(2, 4),
        playerName: cleanName,
        score: Math.max(0, score),
        mode: cleanMode,
        streak: streak || 0,
        avatar: avatar || '🏀',
        country: country || 'VN',
        timestamp: Date.now(),
        ballSkinId: ballSkinId || 'standard'
      };
      leaderboardData.push(entry);
      isNewRecord = true;
    }

    // Sort leaderboard mode entries
    const modeLeaderboard = leaderboardData
      .filter((item) => item.mode === cleanMode)
      .sort((a, b) => b.score - a.score);

    const rank = modeLeaderboard.findIndex((item) => item.id === entry.id) + 1;

    res.json({
      success: true,
      entry,
      rank,
      isNewRecord,
      message: isNewRecord ? 'Kỷ lục mới đã được lưu!' : 'Đã cập nhật bảng xếp hạng!'
    });
  });

  // Calculate rank for a score
  app.get("/api/leaderboard/my-rank", (req, res) => {
    const score = parseInt((req.query.score as string) || '0', 10);
    const mode = (req.query.mode as string) || 'arcade';

    const higherScores = leaderboardData.filter(
      (item) => item.mode === mode && item.score > score
    ).length;

    res.json({
      rank: higherScores + 1,
      totalPlayers: leaderboardData.filter((item) => item.mode === mode).length
    });
  });

  // Vite Middleware for development vs static serve for production
  if (process.env.NODE_ENV !== "production") {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), 'dist');
    app.use(express.static(distPath));
    app.get('*', (req, res) => {
      res.sendFile(path.join(distPath, 'index.html'));
    });
  }

  app.listen(PORT, "0.0.0.0", () => {
    console.log(`Server running on http://localhost:${PORT}`);
  });
}

startServer();
